# The leftmost ring is visibly held after the lift, and the center cell is empty.
# I will place it at the calibrated center, clear vertically, and hold home for the opponent.
def place_held_ring(arm, destination, quaternion, wait_steps):
    stages = [
        ('transfer', [destination[0], destination[1], 0.99] + quaternion, 0.0, 33),
        ('lower', destination + quaternion, 0.0, 15),
        ('release', None, 1.0, 8),
        ('clear', [destination[0], destination[1], 0.99] + quaternion, 1.0, 18),
        ('home_wait', None, 1.0, wait_steps),
    ]
    for label, target, grip, cap in stages:
        if label == 'home_wait':
            obs, result = hold_action(home_action, cap)
        elif target is None:
            obs, result = hold_joints(cap, {arm: grip})
        else:
            obs, result = ee_move(arm, target, grip, max_steps=cap, max_delta=0.014 if label == 'transfer' else 0.007, settle_steps=2)
        print(label, result)
        if result['terminated'] or result['truncated'] or (target is not None and not result['reached']):
            return obs, result
    return obs, result
obs, result = place_held_ring('left', [0.0, -0.075, 0.955], q_pick, 145)
print('state', obs['state'])

